    23	int main(int argc, char** argv) {
    24	  if (argc < 3 || argc > 4) return 2;
    25	  const std::uint64_t frames = std::strtoull(argv[1], nullptr, 10);
    26	  const std::uint64_t seed = std::strtoull(argv[2], nullptr, 10);
    27	  const bool audit = argc == 4 && std::string(argv[3]) == "--audit";
    28	  constexpr std::uint64_t input_rate = 44100;
    29	  constexpr std::uint64_t output_rate = 48000;
    30	  constexpr int channels = 2;
    31	  if (!frames || frames > 500000 || (argc == 4 && !audit) || (audit && frames > 65536)) return 2;
