    33	  // k is emitted exactly when k * input_rate is strictly before the last
    34	  // input timestamp, so the number of outputs is ceil((frames-1)*out/in).
    35	  const std::uint64_t span = (frames - 1) * output_rate;
    36	  const std::uint64_t outputs = (span + input_rate - 1) / input_rate;
