    38	  std::cout.precision(audit ? 17 : 9);
    39	  std::cout << outputs << '\n';
    40	  for (std::uint64_t k = 0; k < outputs; ++k) {
    41	    const std::uint64_t position = k * input_rate;
    42	    const std::uint64_t index = position / output_rate;
    43	    const std::uint64_t remainder = position % output_rate;
    44	    if (audit) {
    45	      const double fraction = static_cast<double>(remainder) / output_rate;
    46	      for (int c = 0; c < channels; ++c) {
    47	        const double a = input_sample(index, c, seed);
    48	        const double b = input_sample(index + 1, c, seed);
    49	        std::cout << a + fraction * (b - a) << (c ? '\n' : ' ');
    50	      }
    51	    } else {
    52	      // The input range is bounded by +/-1. Each sample is quantized in
    53	      // 1e-6 increments, so binary32 interpolation remains far inside the
    54	      // 2e-6 output tolerance while avoiding unnecessary wide hot-loop math.
    55	      const float fraction = static_cast<float>(remainder) / static_cast<float>(output_rate);
    56	      for (int c = 0; c < channels; ++c) {
    57	        const float a = input_sample_float(index, c, seed);
    58	        const float b = input_sample_float(index + 1, c, seed);
    59	        const float value = a + fraction * (b - a);
    60	        std::cout << value << (c ? '\n' : ' ');
    61	      }
    62	    }
    63	  }
    64	}

